const x=[["x","sx"],["y","sy"],["z","sz"]],y=1e-7;export const bounds=t=>x.map(([n,o])=>[t[n]-t[o]/2,t[n]+t[o]/2]);export function intersects(t,n){return t.every((o,r)=>Math.min(o[1],n[r][1])-Math.max(o[0],n[r][0])>1e-7)}export function subtractBox(t,n){if(!intersects(t,n))return[t];const o=t.map(e=>[...e]),r=[];for(let e=0;e<3;e++){const a=Math.max(o[e][0],n[e][0]),l=Math.min(o[e][1],n[e][1]);if(o[e][0]<a-1e-7){const c=o.map(f=>[...f]);c[e][1]=a,r.push(c),o[e][0]=a}if(o[e][1]>l+1e-7){const c=o.map(f=>[...f]);c[e][0]=l,r.push(c),o[e][1]=l}}return r}const p=t=>{const n=[];for(let o=Math.floor(t[0][0]/2);o<=Math.floor(t[0][1]/2);o++)for(let r=Math.floor(t[1][0]/2);r<=Math.floor(t[1][1]/2);r++)for(let e=Math.floor(t[2][0]/2);e<=Math.floor(t[2][1]/2);e++)n.push(`${o},${r},${e}`);return n};export function compileSolids(t){const n=new Map,o=c=>{for(const f of p(c))n.has(f)||n.set(f,[]),n.get(f).push(c)},r=(c,f)=>c.flatMap(h=>{const u=bounds(h),M=new Set(p(u).flatMap(s=>n.get(s)||[]));let i=[u];for(const s of M)if(i=i.flatMap(m=>subtractBox(m,s)),!i.length)break;if(f)for(const s of i)o(s);return i.map(s=>({...h,x:(s[0][0]+s[0][1])/2,y:(s[1][0]+s[1][1])/2,z:(s[2][0]+s[2][1])/2,sx:s[0][1]-s[0][0],sy:s[1][1]-s[1][0],sz:s[2][1]-s[2][0]}))}),e=r(t.base,!0),a=r(t.excavation,!1),l=r(t.blocks,!0);return{base:e,blocks:l,excavation:a}}
